Lemma ta_rel_set_gai sc st b ai : 0 <= Z.land ai 31 <= 31 ->
  (forall h g, (s_groups st) !! b = Some h -> g_meta h = Some g -> m_sizeclass (get_meta_rec st g) <> 0) ->
