Lemma ALLC_tick st0 t :
  (forall rid sh o v tk, (s_shadow st0) !! rid = Some sh -> (r_cells sh) !! o = Some (v, tk) -> (tk <= s_tick st0)%N) ->
  (s_tick st0 < t)%N -> ALLC (set_tick t st0).
Proof.
